package cn.xinji.agentplatform.adjudication.casework;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.io.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import com.fasterxml.jackson.databind.*;
public final class AdjudicationEnvelope {
 static final ObjectMapper JSON=new ObjectMapper();static Path out;static final String CONTAINER="agent-platform-single-persistent-primary-dm8-02-20261007",DIR="/opt/dmdbms/data/adjudication-report-engineering-01",DUMP="adjudication-main-v1.dmp";
 static final byte[] MAGIC="XJADJGCM1".getBytes(StandardCharsets.US_ASCII),AAD="VER-ADJ-SINGLE-DB-REPORT-RECOVERY-01:OWNED-MAIN-AND-EXACT-ORIGINALS:v1".getBytes(StandardCharsets.US_ASCII);
 static final List<String> FILES=List.of("owned-input/manifest.json","owned-input/records.json","main-active-baseline.json","product-active-state.json","product-active-versions.json","product-command-receipts.json","product-active-originals.json","engineering-coordinate-mapping.json");
 record Exec(int code,byte[] output){}
 static Exec exec(List<String> args,byte[] input)throws Exception{var p=new ProcessBuilder(args).redirectErrorStream(true).start();try(var stdin=p.getOutputStream()){if(input!=null)stdin.write(input);}byte[] bytes=p.getInputStream().readNBytes(96*1024*1024+1);if(bytes.length>96*1024*1024){p.destroyForcibly();throw new IllegalStateException("Owned process output limit exceeded");}return new Exec(p.waitFor(),bytes);}
 static List<String> docker(String... tail){var r=new ArrayList<String>(List.of("docker","exec","-i","--user","1000:1000",CONTAINER));r.addAll(List.of(tail));return r;}
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 static void write(String name,Object data)throws Exception{Files.write(out.resolve(name),JSON.writerWithDefaultPrettyPrinter().writeValueAsBytes(data),StandardOpenOption.CREATE_NEW);}
 static byte[] key(){return Base64.getDecoder().decode(System.getenv("ADJ_ENVELOPE_KEY"));}
 static byte[] decrypt(byte[] sealed)throws Exception{if(sealed.length<37||sealed.length>96*1024*1024||!Arrays.equals(Arrays.copyOf(sealed,9),MAGIC))throw new IllegalArgumentException("Envelope size/header");var cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key(),"AES"),new GCMParameterSpec(128,Arrays.copyOfRange(sealed,9,21)));cipher.updateAAD(AAD);return cipher.doFinal(Arrays.copyOfRange(sealed,21,sealed.length));}
 static JsonNode validate(byte[] raw)throws Exception{var b=JSON.readTree(raw);if(!b.path("task").asText().equals("VER-ADJ-SINGLE-DB-REPORT-RECOVERY-01")||!b.path("nativeSchema").asText().equals("ADJENGMAIN")||b.path("files").size()!=FILES.size())throw new IllegalStateException("Exact scope invalid");int i=0;for(var f:b.path("files")){if(!f.path("path").asText().equals(FILES.get(i++)))throw new IllegalStateException("Exact file allowlist mismatch");byte[] bytes=Base64.getDecoder().decode(f.path("base64").asText());if(bytes.length!=f.path("bytes").asInt()||!sha(bytes).equals(f.path("sha256").asText()))throw new IllegalStateException("File bytes authentication mismatch");}byte[] nativeBytes=Base64.getDecoder().decode(b.path("nativeBase64").asText());if(!sha(nativeBytes).equals(b.path("nativeSha256").asText())||nativeBytes.length!=b.path("nativeBytes").asInt())throw new IllegalStateException("Native inventory mismatch");return b;}
 public static void main(String[] args)throws Exception{out=Path.of(System.getenv("ADJ_OUTPUT"));String action=args[0];Path bundle=out.resolve("adjudication-native-and-originals-v1.gcm");
  if(action.equals("export")){
   String script="IFS= read -r p; p=$(printf %s \"$p\" | tr -d '\\r'); umask 077; test ! -e "+DIR+" || exit 91; mkdir "+DIR+" || exit 92; /opt/dmdbms/bin/dexp \"ADJENGMAIN/$p@127.0.0.1:5236\" SCHEMAS=ADJENGMAIN FILE="+DUMP+" DIRECTORY="+DIR+" GRANTS=N NOLOGFILE=Y";
   String secret=System.getenv("ADJ_ADJENGMAIN_PASSWORD");var r=exec(docker("/bin/sh","-c",script),(secret+"\n").getBytes(StandardCharsets.UTF_8));String text=new String(r.output(),StandardCharsets.UTF_8).replace(secret,"[REDACTED]");Files.writeString(out.resolve("native-export.log"),text,StandardOpenOption.CREATE_NEW);write("native-export-result.json",Map.of("exitCode",r.code(),"schema","ADJENGMAIN","authorityExported",false,"grantsExported",false));if(r.code()!=0)throw new IllegalStateException("Owned native export failed");
  }else if(action.equals("seal")){
   var r=exec(docker("cat",DIR+"/"+DUMP),null);if(r.code()!=0)throw new IllegalStateException("Native read failed");var b=JSON.createObjectNode().put("task","VER-ADJ-SINGLE-DB-REPORT-RECOVERY-01").put("nativeSchema","ADJENGMAIN").put("nativeBytes",r.output().length).put("nativeSha256",sha(r.output())).put("nativeBase64",Base64.getEncoder().encodeToString(r.output()));var files=b.putArray("files");for(String f:FILES){byte[] bytes=Files.readAllBytes(out.resolve(f));if(bytes.length>1024*1024)throw new IllegalStateException("Owned file package limit");files.addObject().put("path",f).put("bytes",bytes.length).put("sha256",sha(bytes)).put("base64",Base64.getEncoder().encodeToString(bytes));}byte[] raw=JSON.writeValueAsBytes(b);validate(raw);var nonce=new byte[12];new SecureRandom().nextBytes(nonce);var cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key(),"AES"),new GCMParameterSpec(128,nonce));cipher.updateAAD(AAD);var encrypted=cipher.doFinal(raw);var result=new ByteArrayOutputStream();result.write(MAGIC);result.write(nonce);result.write(encrypted);Files.write(bundle,result.toByteArray(),StandardOpenOption.CREATE_NEW);write("seal-receipt.json",Map.of("nativeBytes",r.output().length,"nativeSha256",sha(r.output()),"cipher","AES-256-GCM","sealedBytes",result.size(),"sealedSha256",sha(result.toByteArray()),"authenticatedFiles",FILES,"AUTHExcluded",true,"plaintextNativeOnHost",false));Arrays.fill(raw,(byte)0);Arrays.fill(r.output(),(byte)0);
  }else if(action.equals("tamper")){
   var sealed=Files.readAllBytes(bundle);sealed[sealed.length-1]^=1;boolean refused=false;String exception="";try{decrypt(sealed);}catch(AEADBadTagException e){refused=true;exception=e.getClass().getName();}if(!refused)throw new IllegalStateException("Tampered envelope accepted");write("tamper-rejection.json",Map.of("authenticationRejected",true,"actualException",exception,"targetContacted",false,"originalsWritten",false,"databaseWrites",0));
  }else if(action.equals("deliver")){
   byte[] sealed=Files.readAllBytes(bundle);byte[] raw=decrypt(sealed);JsonNode b=validate(raw); // complete authentication and inventory checks before any target contact/extraction
   Path originals=out.resolve("authenticated-restored-input");Files.createDirectory(originals);for(var f:b.path("files")){String name=f.path("path").asText();if(name.startsWith("owned-input/"))Files.write(originals.resolve(name.substring("owned-input/".length())),Base64.getDecoder().decode(f.path("base64").asText()),StandardOpenOption.CREATE_NEW);}
   byte[] nativeBytes=Base64.getDecoder().decode(b.path("nativeBase64").asText());var r=exec(docker("/bin/sh","-c","umask 077; set -C; cat > "+DIR+"/authenticated-restore-v1.dmp"),nativeBytes);if(r.code()!=0)throw new IllegalStateException("Owned native delivery failed");write("authenticated-delivery-receipt.json",Map.of("authenticatedBeforeTargetContact",true,"nativeBytes",nativeBytes.length,"nativeSha256",sha(nativeBytes),"sealedSha256",sha(sealed),"AUTHExcluded",true,"plaintextNativeOnHost",false));Arrays.fill(raw,(byte)0);Arrays.fill(nativeBytes,(byte)0);
  }else if(action.equals("import")){
   // Non-SYS owner with no MAIN privileges: any wrong-target behavior must fail, never overwrite MAIN.
   String script="IFS= read -r p; p=$(printf %s \"$p\" | tr -d '\\r'); /opt/dmdbms/bin/dimp \"ADJENGREST/$p@127.0.0.1:5236\" SCHEMAS=ADJENGMAIN FILE=authenticated-restore-v1.dmp DIRECTORY="+DIR+" GRANTS=N IGNORE=N NOLOGFILE=Y";
   String secret=System.getenv("ADJ_ADJENGREST_PASSWORD");var r=exec(docker("/bin/sh","-c",script),(secret+"\n").getBytes(StandardCharsets.UTF_8));String text=new String(r.output(),StandardCharsets.UTF_8).replace(secret,"[REDACTED]");Files.writeString(out.resolve("native-import.log"),text,StandardOpenOption.CREATE_NEW);write("native-import-result.json",Map.of("exitCode",r.code(),"sourceSchema","ADJENGMAIN","targetOwner","ADJENGREST","noSysDbaImport",true,"AUTHImported",false));if(r.code()!=0)throw new IllegalStateException("Native cross-schema import unavailable; inspect actual native log");
  }else throw new IllegalArgumentException("Unsupported action");System.out.println("envelope "+action+" exit0");
 }
}

